# Note: tests 393-406 have the same structure. For a full import, run fetch_more_tests.py
# and pass the JSON file path as argument, or embed all tests above.
# This file contains tests 392 and 580 as a demonstration. 
# To import all 16 tests, load the full data from the browser result file.


def build_card(test_data: dict, q: dict, user_id: str) -> dict:
    """Convert a yeshiva.org.il question to a card record."""
    answers = q["answers"]
    # correct is 1-based index list → convert to 0-based
    correct_indices = [c - 1 for c in q["correct"]]
    
    test_title = test_data["title"]
    mekorot = test_data.get("mekorot", "")
    
    tags = [
        f"מסכת:{MASECHET_TAG}",
        f"מבחן:{test_title}",
        f"מקורות:{mekorot}" if mekorot else "",
        SOURCE_TAG,
    ]
    tags = [t for t in tags if t]
    
    now = datetime.now(timezone.utc).isoformat()
    return {
        "id": str(uuid.uuid4()),
        "type": "multiple",
        "question": q["question"],
        "answer": answers[correct_indices[0]] if correct_indices else "",
        "options": answers,
        "correct_indices": correct_indices,
        "correct_boolean": None,
        "explanation": None,
        "tags": tags,
        "srs": {
            "interval": 1,
            "ease": 2.5,
            "due": now,
            "reviews": 0,
            "lapses": 0,
        },
        "stats": {
            "correct": 0,
            "incorrect": 0,
            "streak": 0,
        },
        "created_at": now,
        "updated_at": now,
        "user_id": user_id,
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--dry-run", action="store_true", help="אל תכניס לבסיס הנתונים")
    parser.add_argument("--data-file", help="קובץ JSON עם נתוני המבחנים (אופציונלי)")
    args = parser.parse_args()
    
    tests_data = TESTS_DATA
    if args.data_file:
        with open(args.data_file, encoding="utf-8") as f:
            tests_data = json.load(f)
        print(f"📂 נטען קובץ נתונים: {args.data_file} ({len(tests_data)} מבחנים)")
    
    print(f"🔐 מתחבר לסופאבייס...")
    token, user_id = login()
    print(f"✅ מחובר")
    
    all_cards = []
    for test_id, test_data in tests_data.items():
        questions = test_data.get("questions", [])
        if not questions:
            print(f"  ⚠️  מבחן {test_id} ({test_data.get('title','')}) ללא שאלות - מדלג")
            continue
        
        for q in questions:
            card = build_card(test_data, q, user_id)
            all_cards.append(card)
        
        print(f"  📝 מבחן {test_id} ({test_data.get('title','')}) — {len(questions)} שאלות")
    
    print(f"\n📊 סה\"כ {len(all_cards)} כרטיסיות")
    
    if args.dry_run:
        print("🔍 Dry run — לא מכניס לבסיס הנתונים")
        print(json.dumps(all_cards[0], ensure_ascii=False, indent=2))
        return
    
    # Insert in batches of 50
    BATCH = 50
    inserted = 0
    for i in range(0, len(all_cards), BATCH):
        batch = all_cards[i:i+BATCH]
        n = insert_cards(token, batch)
        inserted += n
        print(f"  ✅ הוכנסו {inserted}/{len(all_cards)} כרטיסיות")
        time.sleep(0.3)
    
    print(f"\n🎉 הושלם! הוכנסו {inserted} כרטיסיות ממסכת {MASECHET_TAG}")


if __name__ == "__main__":
    main()
